import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.B0p3fmqd.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"towscenarios/changelog.md","filePath":"towscenarios/changelog.md","lastUpdated":1791036569000}'),o={name:"towscenarios/changelog.md"};function n(l,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_5-0-4" tabindex="-1">5.0.4 <a class="header-anchor" href="#_5-0-4" aria-label="Permalink to &quot;5.0.4&quot;">​</a></h2><h3 id="new" tabindex="-1">New <a class="header-anchor" href="#new" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li>Tow scenes now find drivers who arrive late or drive into range on their own, instead of waiting on a repeated announcement.</li><li>Tow fires can flare back up after being put out, and a burning car explodes, with a warning first, if nobody puts it out in time. Its payout is reduced when it does.</li><li>New call-out: a car fire at the roadside. Put it out with a fire extinguisher before it explodes, then recover the wreck.</li><li>Fire scenes feel more alive: nearby pedestrians may flee or stop to film.</li><li>Two new crash scenarios: a head-on collision and a vehicle rollover. Both are posed and damaged where they were hit and leave their hazard lights blinking.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed a crash that could happen if the script restarted while someone was using a defibrillator on an ambulance scene.</li><li>Fixed the ambulance and paramedic not being cleaned up if the script restarted while they were driving to the call.</li><li>Fixed leftover props (the crowbar used to force a door, and the item handed over at the spares shop) if the script restarted mid-animation.</li><li>The fire bonus now goes to the player who actually sprayed the fire.</li><li>A tow driver far from a scene can no longer report a fire out from a distance.</li></ul>',6)])])}const p=a(o,[["render",n]]);export{u as __pageData,p as default};
